"""Exception definitions."""

import typing

from jsilib import _utils, exc

__all__ = export = _utils.ExportList()


@export
class AIOError(exc.JSILIBError):
    """Base class for transport layer errors."""


@export
class IOError(AIOError):
    """Generic exception for an I/O related errors.

    :param message:
        A short description of what happened.

    :param original_exc:
        Original exception that caused failure.
    """

    def __init__(self, message: str, original_exc: Exception = None):
        super().__init__()
        self._message = message
        self._original_exc = original_exc

    def __message_template__(self) -> str:
        if self._original_exc is not None:
            return "{self.message} (caused by: {self.original_exc!r})"
        return "{self.message}"

    @property
    def message(self) -> str:
        return self._message

    @property
    def original_exc(self) -> typing.Optional[Exception]:
        return self._original_exc


@export
class StreamError(AIOError):
    """Base class for stream related errors."""


@export
class StreamClosedError(StreamError):
    """Raised when operation on a closed stream was performed."""


@export
class StreamEOFError(StreamError):
    """Raised when unexpected end of stream was reached during reading."""


@export
class StreamOverflowError(StreamError):
    """Raised when stream unexpectedly refused to accept more data during
    writing.

    This is opposite to :exc:`EOFError`.
    """


@export
class ConnectFailedError(AIOError):
    """Raised when connecting with remote server fails."""

    def __init__(self, message: str, original_exc: Exception = None):
        super().__init__()
        self._message = message
        self._original_exc = original_exc

    @property
    def __message_template__(self) -> str:
        if self.original_exc is None:
            return "{self.message}"
        return "{self.message} ({self.original_exc.__class__.__qualname__}: {self.original_exc})"

    @property
    def message(self) -> str:
        return self._message

    @property
    def original_exc(self) -> typing.Optional[Exception]:
        return self._original_exc


@export
class BindFailedError(AIOError):
    """Raised when server was not able to bind to a given address."""

    def __init__(self, message: str, original_exc: Exception = None):
        super().__init__()
        self._message = message
        self._original_exc = original_exc

    @property
    def __message_template__(self) -> str:
        if self.original_exc is None:
            return "{self.message}"
        return "{self.message} ({self.original_exc.__class__.__qualname__}: {self.original_exc})"

    @property
    def message(self) -> str:
        return self._message

    @property
    def original_exc(self) -> typing.Optional[Exception]:
        return self._original_exc


@export
class AcceptorClosedError(AIOError):
    """Raised when :meth:`IAcceptor.accept` is terminated by closing acceptor
    object or when called on an already closed acceptor."""
